function plan(shots){ if(!Array.isArray(shots)) return {error:'shots 须为数组'};
  var total=0; for(var i=0;i<shots.length;i++) total+=(+shots[i].dur||0);
  var bySize={}; for(var j=0;j<shots.length;j++){ var s=shots[j].size||'medium'; bySize[s]=(bySize[s]||0)+1; }
  return {count:shots.length, total:total, bySize:bySize}; }
var EXPORTS={plan:plan};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StoryboardForgePure = EXPORTS; }
